fn solve(input: Vec<char>) -> Vec<char> {
    // The input must start with "AtCoder "
    let prefix = ['A','t','C','o','d','e','r',' '];
    for i in 0..prefix.len() {
        if input[i] != prefix[i] {
            // According to the problem, input always satisfies format,
            // so no error handling needed. Just return empty if bad.
            return vec![];
        }
    }

    // After "AtCoder ", parse the name word:
    // First character uppercase 'A'-'Z'
    let name_start = prefix.len();
    let name_initial = input[name_start];
    if !name_initial.is_ascii_uppercase() {
        return vec![];
    }

    // Then every next character until next space must be lowercase a-z
    let mut idx = name_start + 1;
    while idx < input.len() && input[idx] != ' ' {
        if !input[idx].is_ascii_lowercase() {
            return vec![];
        }
        idx += 1;
    }

    // After the name, there must be a space, then "Contest", then newline at the end.
    // Check that after idx is a space
    if idx >= input.len() || input[idx] != ' ' {
        return vec![];
    }
    idx += 1;

    // Check that "Contest" appears here
    let contest = ['C','o','n','t','e','s','t'];
    for i in 0..contest.len() {
        if idx + i >= input.len() || input[idx + i] != contest[i] {
            return vec![];
        }
    }
    idx += contest.len();

    // Check last char is '\n' and input length matches idx
    if idx != input.len() - 1 || input[idx] != '\n' {
        return vec![];
    }

    build_result(name_initial)
}

fn build_result(ch: char) -> Vec<char> {
    // "A<NameInitial>C\n"
    vec!['A', ch, 'C', '\n']
}